import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect if input is adjacency matrix (square and binary 0/1)
    is_matrix = False
    if len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and degree list
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
        deg = [len(adj_list[i]) for i in range(n)]
    else:
        adj_list = adj
        deg = [len(adj_list[i]) for i in range(n)]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: compute number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    best_coloring = None
    best_k = float('inf')

    # Strategy 1: DSATUR
    def dsatur():
        color = [-1] * n
        # saturation: list of sets of neighbor colors
        saturation = [set() for _ in range(n)]
        uncolored = set(range(n))
        # initial degrees in the uncolored subgraph
        deg_uncolored = deg[:]
        while uncolored:
            # select vertex with max saturation, tie-break by max deg_uncolored, then random
            v = max(uncolored, key=lambda x: (len(saturation[x]), deg_uncolored[x], random.random()))
            # find smallest available color
            used = [False] * n
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation and deg_uncolored for neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u].add(c)
                    deg_uncolored[u] -= 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0
        while uncolored:
            # build independent set for current_color
            # deg in induced subgraph of uncolored
            deg_sub = {v: 0 for v in uncolored}
            for v in uncolored:
                for u in adj_list[v]:
                    if u in uncolored:
                        deg_sub[v] += 1
            # start with vertex of max degree in uncolored
            v = max(uncolored, key=lambda x: (deg_sub[x], random.random()))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            # W: vertices adjacent to at least one in independent_set
            U = uncolored - {v} - set(adj_list[v])
            W = set(adj_list[v]) & uncolored
            while U:
                # select u in U with max |N(u) ∩ W|, tie-break by min deg in U
                best_u = None
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    # count neighbors in W
                    cnt = 0
                    for w in adj_list[u]:
                        if w in W:
                            cnt += 1
                    # degree in U
                    deg_u = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_u += 1
                    if cnt > best_score or (cnt == best_score and deg_u < best_deg_U):
                        best_score = cnt
                        best_deg_U = deg_u
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to independent_set
            for v in independent_set:
                color[v] = current_color
            uncolored -= independent_set
            current_color += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # core decomposition to get ordering
        deg_copy = deg[:]
        visited = [False] * n
        order = []
        buckets = [[] for _ in range(n)]  # degree can be up to n-1
        for v in range(n):
            d = deg_copy[v]
            if d < n:
                buckets[d].append(v)
        # pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # find non-empty bucket
            while ptr < n and not buckets[ptr]:
                ptr += 1
            if ptr >= n:
                break  # should not happen
            v = buckets[ptr].pop()
            if visited[v]:
                # find another
                while buckets[ptr] and visited[buckets[ptr][-1]]:
                    buckets[ptr].pop()
                if not buckets[ptr]:
                    ptr += 1
                    while ptr < n and not buckets[ptr]:
                        ptr += 1
                    if ptr >= n:
                        break
                    v = buckets[ptr].pop()
            visited[v] = True
            order.append(v)
            # decrease degree of unvisited neighbors
            for u in adj_list[v]:
                if not visited[u]:
                    d_u = deg_copy[u]
                    if d_u > 0:
                        deg_copy[u] -= 1
                        buckets[d_u].remove(v)  # This is inefficient, but n <= 100
                        buckets[d_u - 1].append(u)
        # color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Welsh-Powell (degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: (-deg[x], random.random()))
        return greedy_color(order)

    # Try all strategies
    strategies = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Smallest-Last", smallest_last),
        ("Welsh-Powell", welsh_powell)
    ]

    for name, func in strategies:
        try:
            coloring = func()
            k = num_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring
                # early exit if we found optimal (lower bound: max clique size, but we use a simple bound: if k <= max_degree+1, not necessarily optimal)
                # We can't easily compute clique, so we don't exit early.
        except Exception:
            # In case of any error, skip this strategy
            continue

    # If no strategy succeeded (should not happen), fallback to Welsh-Powell
    if best_coloring is None:
        best_coloring = welsh_powell()

    return best_coloring

