import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)

    # Detect adjacency matrix: square and binary entries (0 or 1)
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for row in adj:
            if len(row) != n or any(x not in (0, 1) for x in row):
                is_matrix = False
                break

    # Build neighbor list and degree array
    neighbors = [[] for _ in range(n)]
    degree = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
        degree = [len(neighbors[i]) for i in range(n)]
    else:
        for i in range(n):
            neighbors[i] = list(adj[i])
        degree = [len(neighbors[i]) for i in range(n)]

    # Trivial cases
    if n == 1:
        return [0]
    if all(d == 0 for d in degree):
        return [0] * n

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: count colors used
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                c = coloring[u]
                if c != -1:
                    used[c] = True
            for c in range(n):
                if not used[c]:
                    coloring[v] = c
                    break
        return coloring

    # Helper: DSATUR with bitmask optimization
    def dsatur():
        coloring = [-1] * n
        saturation = [0] * n
        neighbor_colors = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))

        while uncolored:
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_v = saturation[v]
                deg_uncolored = 0
                for u in neighbors[v]:
                    if u in uncolored:
                        deg_uncolored += 1
                if sat_v > best_sat or (sat_v == best_sat and deg_uncolored > best_deg) or \
                   (sat_v == best_sat and deg_uncolored == best_deg and random.random() < 0.5):
                    best_sat = sat_v
                    best_deg = deg_uncolored
                    best_v = v
            v = best_v

            used_mask = neighbor_colors[v]
            c = 0
            while used_mask & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)

            for u in neighbors[v]:
                if u in uncolored:
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] += 1
        return coloring

    # Helper: RLF (Largest First Independent Set Extraction)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Compute degree in uncolored subgraph
            deg_uncolored = {}
            for v in uncolored:
                cnt = 0
                for u in neighbors[v]:
                    if u in uncolored:
                        cnt += 1
                deg_uncolored[v] = cnt
            # Select vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            S = [v]
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                # Check if u is adjacent to any in S
                adjacent = False
                for w in S:
                    if u in neighbors[w]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)
            while U:
                best_u = -1
                best_score = -1
                best_deg_u = -1
                for u in U:
                    score = 0
                    for w in neighbors[u]:
                        if w in W:
                            score += 1
                    deg_u = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_u += 1
                    if score > best_score or (score == best_score and deg_u < best_deg_u) or \
                       (score == best_score and deg_u == best_deg_u and random.random() < 0.5):
                        best_score = score
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.append(u)
                U.remove(u)
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            for v in S:
                coloring[v] = color
                uncolored.remove(v)
            color += 1
        return coloring

    # Helper: Welsh-Powell (degree ordering)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: degree[x], reverse=True)
        return greedy_color(order)

    # Helper: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        deg = degree[:]
        deleted = [False] * n
        order = []
        for _ in range(n):
            min_deg = n
            min_v = -1
            for v in range(n):
                if not deleted[v]:
                    d = 0
                    for u in neighbors[v]:
                        if not deleted[u]:
                            d += 1
                    if d < min_deg:
                        min_deg = d
                        min_v = v
            deleted[min_v] = True
            order.append(min_v)
            for u in neighbors[min_v]:
                if not deleted[u]:
                    deg[u] -= 1
        return greedy_color(list(reversed(order)))

    # Kempe chain local search for color class elimination (optimized)
    def kempe_local_search(coloring):
        current = coloring[:]
        k = count_colors(current)
        if k <= 1:
            return current

        # Precompute neighbor sets for fast lookup
        neighbor_sets = [set(neighbors[i]) for i in range(n)]

        improved = True
        # Limit rounds to avoid excessive computation; 5 is usually enough for n<=100
        for _ in range(5):
            if not improved or k <= 1:
                break
            improved = False
            target_color = k - 1
            # Get vertices with target color
            vertices = [v for v in range(n) if current[v] == target_color]
            if not vertices:
                k -= 1
                improved = True
                continue
            random.shuffle(vertices)

            for v in vertices:
                # Try to move v to a lower color directly
                neighbor_colors = set()
                for u in neighbors[v]:
                    if current[u] != -1:
                        neighbor_colors.add(current[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        current[v] = c
                        improved = True
                        break
                if improved:
                    if target_color not in current:
                        k -= 1
                    break

                # Try Kempe chains for each lower color
                for c in range(target_color):
                    # BFS to get the (c, target_color) Kempe chain containing v
                    visited = [False] * n
                    stack = [v]
                    visited[v] = True
                    component = []
                    while stack:
                        x = stack.pop()
                        component.append(x)
                        for y in neighbors[x]:
                            if not visited[y] and (current[y] == c or current[y] == target_color):
                                visited[y] = True
                                stack.append(y)

                    # Check if swapping is safe: no neighbor of v gets color c after swap
                    safe = True
                    for u in neighbors[v]:
                        if current[u] == -1:
                            continue
                        if u in component:
                            new_col = c if current[u] == target_color else target_color if current[u] == c else current[u]
                        else:
                            new_col = current[u]
                        if new_col == c:
                            safe = False
                            break
                    if not safe:
                        continue

                    # Count colors in component to see if swap reduces target color count
                    count_target = 0
                    count_c = 0
                    for x in component:
                        if current[x] == target_color:
                            count_target += 1
                        elif current[x] == c:
                            count_c += 1
                    if count_c < count_target:
                        # Perform swap
                        for x in component:
                            if current[x] == c:
                                current[x] = target_color
                            elif current[x] == target_color:
                                current[x] = c
                        improved = True
                        break
                if improved:
                    break
            if improved:
                k = count_colors(current)
        return current

    # Run multiple algorithms and select the best (fewest colors)
    methods = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Welsh-Powell", welsh_powell),
        ("Smallest-Last", smallest_last),
    ]
    random.shuffle(methods)  # Avoid order bias
    best_coloring = None
    best_colors = float('inf')
    for name, method in methods:
        try:
            coloring = method()
            if not is_valid_coloring(coloring):
                continue
            colors_used = count_colors(coloring)
            if colors_used < best_colors:
                best_colors = colors_used
                best_coloring = coloring
                if best_colors == 1:  # Optimal for edgeless graphs
                    break
        except Exception:
            continue

    # Fallback: greedy with random order if all methods failed
    if best_coloring is None:
        order = list(range(n))
        random.shuffle(order)
        best_coloring = greedy_color(order)

    # Apply Kempe local search to improve the best coloring
    best_coloring = kempe_local_search(best_coloring)

    # Final validation (should be valid by construction)
    if not is_valid_coloring(best_coloring):
        # Fallback to DSATUR if local search somehow produced invalid coloring
        best_coloring = dsatur()

    return best_coloring
